            open_count += 1
        elif char == ')':
            close_count += 1

    if open_count != close_count:
        return False

    stack = []
    for char in brackets:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()

    return len(stack) == 0
